1496	/// A publish document that passed every check that can run before
1497	/// taking the package lock: the caller may publish the package, and
1498	/// each attachment maps to a canonical disk filename and a
1499	/// `versions[v].dist` block.
1500	struct ValidatedPublish {
1501	    name: PackageName,
1502	    /// The publish body with `_attachments` stripped.
1503	    incoming: Value,
1504	    /// One entry per attachment.
1505	    prepared: Vec<PreparedAttachment>,
1506	}
1507	
1508	/// One publish attachment resolved to its canonical on-disk filename and its
1509	/// `versions[version].dist` block.
1510	struct PreparedAttachment {
1511	    attachment: PendingAttachment,
1512	    /// Canonical on-disk filename.
1513	    canonical: String,
1514	    /// The matching `dist` block, or `Value::Null` when absent.
1515	    dist: Value,
1516	}
1517	
1518	async fn validate_publish_doc(
1519	    state: &AppState,
1520	    identity: &Identity,
1521	    name: PackageName,
1522	    mut incoming: Value,
1523	) -> Result<ValidatedPublish, RegistryError> {
1524	    authorize(state, identity, name.as_str(), Action::Publish)?;
1525	
1526	    let attachments = extract_attachments(&mut incoming)?;
1527	
1528	    // Resolve each attachment's canonical disk filename + matching
1529	    // `versions[v].dist` block. Attachment names that don't match the
1530	    // package (`bar-1.0.0.tgz` for `foo`) or that try to escape the
1531	    // package dir (`../../etc/passwd.tgz`) are rejected here, before
1532	    // any I/O. The canonical name is what we actually persist — for
1533	    // scoped libnpmpublish bodies the wire form is `@scope/name-version.tgz`
1534	    // but on disk it lives at `<root>/@scope/name/name-version.tgz`,
1535	    // matching what `serve_tarball` expects.
1536	    let mut prepared: Vec<PreparedAttachment> = Vec::with_capacity(attachments.len());
1537	    for attachment in attachments {
1538	        let (canonical, version) = name.parse_tarball_name(&attachment.filename)?;
1539	        let dist = incoming
1540	            .get("versions")
1541	            .and_then(|versions| versions.get(&version))
1542	            .and_then(|manifest| manifest.get("dist"))
1543	            .cloned()
1544	            .unwrap_or(Value::Null);
1545	        prepared.push(PreparedAttachment { attachment, canonical, dist });
1546	    }
1547	    Ok(ValidatedPublish { name, incoming, prepared })
1548	}
1549	
1550	/// A publish whose packument is merged and whose tarballs are fully
1551	/// written to tmp slots — everything verified, nothing visible to
1552	/// readers yet. [`commit_publishes`] makes it visible.
1553	struct StagedPublish {
1554	    name: PackageName,
1555	    merged_bytes: Vec<u8>,
1556	    slots: Vec<crate::storage::TarballSlot>,
1557	}
1558	
1559	/// Merge the incoming packument with the on-disk / upstream state
1560	/// and stream every tarball to a tmp slot. The caller must hold the
1561	/// package lock for `doc.name` from before this call until after
1562	/// [`commit_publishes`]. On error, every tmp file this call wrote is
1563	/// removed.
1564	async fn stage_publish(
1565	    state: &AppState,
1566	    doc: ValidatedPublish,
1567	    now_iso: &str,
1568	) -> Result<StagedPublish, RegistryError> {
1569	    let ValidatedPublish { name, incoming, prepared } = doc;
1570	
1571	    let hosted_bytes = state.inner.storage.read_hosted_packument(&name).await?;
1572	
1573	    // Reject a re-publish of an already-hosted version: published versions
1574	    // are immutable, and npm/verdaccio answer a re-publish with 409. Check
1575	    // every version in the incoming body — not just the ones backed by an
1576	    // attachment, since merge_manifest below consumes the whole `versions`
1577	    // map — against the locally hosted packument only (a version that exists
1578	    // only upstream may still be published here for the first time).
1579	    if let Some(bytes) = hosted_bytes.as_deref() {
1580	        let hosted: Value = serde_json::from_slice(bytes).map_err(RegistryError::Json)?;
1581	        if let Some(hosted_versions) = hosted.get("versions").and_then(Value::as_object)
1582	            && let Some(incoming_versions) = incoming.get("versions").and_then(Value::as_object)
1583	            && let Some(clash) =
1584	                incoming_versions.keys().find(|version| hosted_versions.contains_key(*version))
1585	        {
1586	            return Err(RegistryError::VersionAlreadyPublished {
1587	                package: name.as_str().to_string(),
1588	                version: clash.clone(),
1589	            });
1590	        }
1591	    }
1592	
1593	    // Seed the merge from whatever the upstream knows about the
1594	    // package, not just from a cold cache. Without this, a publish
1595	    // of a brand-new version of an upstream-only package would
1596	    // start from `None` and the newly-written local packument
1597	    // would mask every upstream version + dist-tag on subsequent
1598	    // reads. `update_dist_tag` already does the same fallback —
1599	    // we just mirror it here.
1600	    let existing_bytes = match hosted_bytes {
1601	        Some(bytes) => Some(bytes),
1602	        None => match load_packument_bytes(state, &name).await {
1603	            PackumentLoad::Ok(bytes) => Some(bytes),
1604	            PackumentLoad::NotFound => None,
1605	            PackumentLoad::Err(err) => return Err(err),
1606	        },
1607	    };
1608	    let existing: Option<Value> = match existing_bytes.as_deref().map(serde_json::from_slice) {
1609	        Some(Ok(v)) => Some(v),
1610	        Some(Err(err)) => return Err(RegistryError::Json(err)),
1611	        None => None,
1612	    };
1613	    let merged = merge_manifest(existing.as_ref(), &incoming, now_iso);
1614	    let merged_bytes = serde_json::to_vec_pretty(&merged).map_err(RegistryError::Json)?;
1615	    // `incoming` is no longer needed; drop it so the base64 strings
1616	    // inside go away as soon as `prepared` (which owns each one) is
1617	    // drained below.
1618	    drop(incoming);
1619	
1620	    // Stream-decode + verify + write each tarball. A mismatch — or a
1621	    // missing integrity field — short-circuits the publish with a
1622	    // 400; any tmp files written before the failure get removed
1623	    // along the way so a bad upload leaves no on-disk artifact.
1624	    let mut written_slots = Vec::with_capacity(prepared.len());
1625	    for PreparedAttachment { attachment, canonical, dist } in prepared {
1626	        let slot = match state.inner.storage.reserve_hosted_tarball(&name, &canonical).await {
1627	            Ok(slot) => slot,
1628	            Err(err) => {
1629	                cleanup_tmp_slots(written_slots).await;
1630	                return Err(err);
1631	            }
1632	        };
1633	        let PendingAttachment { filename, data, declared_length } = attachment;
1634	        let tmp_path = slot.tmp_path.clone();
1635	        let dist_for_task = (!dist.is_null()).then_some(dist);
1636	        let result = tokio::task::spawn_blocking(move || {
1637	            let dist_ref = dist_for_task.as_ref();
1638	            stream_decode_verify_and_write(&filename, &data, declared_length, dist_ref, &tmp_path)
1639	        })
1640	        .await;
1641	        match result {
1642	            Ok(Ok(_)) => written_slots.push(slot),
1643	            Ok(Err(err)) => {
1644	                cleanup_tmp_slots(written_slots).await;
1645	                return Err(err);
1646	            }
1647	            Err(join_err) => {
1648	                let _ = tokio::fs::remove_file(&slot.tmp_path).await;
1649	                cleanup_tmp_slots(written_slots).await;
1650	                return Err(RegistryError::Io(std::io::Error::other(join_err.to_string())));
1651	            }
1652	        }
