142	/// Push the streaming loop past its 64 KiB chunk buffer. A
143	/// regression where the loop accidentally returned after the
144	/// first `read` (or where the hasher only saw the first chunk)
145	/// would still pass every smaller-payload test in this module —
146	/// this is the one that catches it.
147	#[test]
148	fn stream_handles_payload_larger_than_chunk_buffer() {
149	    let bytes = vec![0xAB; 200 * 1024];
150	    let dist = json!({ "integrity": sri_sha512(&bytes), "shasum": sha1_hex(&bytes) });
151	    let (result, dest, _tmp) = run_stream(&bytes, Some(&dist), Some(bytes.len() as u64));
152	    let written = result.unwrap();
153	    assert_eq!(written, bytes.len() as u64);
154	    assert_eq!(std::fs::read(&dest).unwrap(), bytes);
155	}
