/// Merge incoming `versions` into the existing `versions` map, holding
/// already-hosted versions immutable. Incoming entries win on key
/// collision, except for versions present in `hosted`'s `versions`
/// map: those keep the hosted entry verbatim, with only `deprecated`
/// taken from the incoming entry (see [`preserve_hosted_version`]).
/// When `hosted` is `None`, this reduces to a plain union with incoming
/// precedence.
fn merge_versions(existing: Option<&Value>, incoming: &Value, hosted: Option<&Value>) -> Value {
    let mut merged = match existing {
        Some(Value::Object(obj)) => obj.clone(),
        _ => Map::new(),
    };
    let hosted_versions =
        hosted.and_then(|h| h.get("versions")).and_then(Value::as_object);
    if let Some(incoming_obj) = incoming.as_object() {
        for (version, value) in incoming_obj {
            match hosted_versions.and_then(|versions| versions.get(version)) {
                Some(hosted_entry) => {
                    merged.insert(version.clone(), preserve_hosted_version(hosted_entry, value));
                }
                None => {
                    merged.insert(version.clone(), value.clone());
                }
            }
        }
    }
    Value::Object(merged)
}

/// Produce the merged entry for an already-hosted version: the hosted
/// entry verbatim (`dist.integrity`, every dependency field, …) with
/// only `deprecated` reconciled against the incoming entry.
///
/// A non-object incoming entry (e.g. `null`) is malformed and ignored
/// entirely — the hosted version is preserved unchanged. For an object
/// incoming entry, an included `deprecated` replaces the hosted value
/// and an omitted one removes the key.
fn preserve_hosted_version(hosted_entry: &Value, incoming_entry: &Value) -> Value {
    let Some(hosted_obj) = hosted_entry.as_object() else {
        return hosted_entry.clone();
    };
    let mut out = hosted_obj.clone();
    if let Some(incoming_obj) = incoming_entry.as_object() {
        match incoming_obj.get("deprecated") {
            Some(deprecated) => {
                out.insert("deprecated".to_string(), deprecated.clone());
            }
            None => {
                out.remove("deprecated");
            }
        }
    }
    Value::Object(out)
